import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, vec3, texture, mul, add } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const node = new THREE.Group();
  node.position.set(0, 1.6, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  // Load ceramic grain texture
  const grainTexture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');

  // Create badge plane geometry (capsule-like)
  const geometry = new THREE.PlaneGeometry(1.0, 0.35);

  // Accent red color from design tokens
  const accentColor = new THREE.Color('#ff2a38');

  // TSL material with grain texture detail
  const grainNode = texture(grainTexture);
  const colorBase = vec3(accentColor.r, accentColor.g, accentColor.b);
  const colorFinal = mul(colorBase, add(vec3(1.0), mul(grainNode.r, 0.15)));

  const material = new MeshBasicNodeMaterial({
    colorNode: colorFinal,
    transparent: true,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  node.add(mesh);

  // Accent edge outline
  const edgeGeometry = new THREE.EdgesGeometry(geometry);
  const edgeMaterial = new THREE.LineBasicMaterial({
    color: accentColor,
    linewidth: 2,
  });
  const edgeLines = new THREE.LineSegments(edgeGeometry, edgeMaterial);
  edgeLines.position.z = 0.005;
  node.add(edgeLines);

  // Manage active timelines
  const timelines = [];

  // Event handlers
  node.userData.handlers = {
    hover: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      // Rise-in effect: lift 0.15 scene units
      const tl = gsap.to(node.position, {
        y: 1.75,
        duration: 0.7,
        ease: 'power3.out',
      });
      timelines.push(tl);
    },

    unhover: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      const tl = gsap.to(node.position, {
        y: 1.6,
        duration: 0.7,
        ease: 'power3.out',
      });
      timelines.push(tl);
    },

    click: () => {
      // Press-down effect: scale to 0.97, then back to 1.0
      const tl = gsap.timeline();
      tl.to(node.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0);
      tl.to(node.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.15,
        ease: 'back.out',
      });
      timelines.push(tl);

      // Emit selection event
      if (config.onSelect) {
        config.onSelect();
      }
    },
  };

  // Cleanup
  node.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    geometry.dispose();
    material.dispose();
    edgeGeometry.dispose();
    edgeMaterial.dispose();
    grainTexture.dispose();
  };

  return node;
}
